using System;
using System.Threading.Tasks; using Microsoft.AspNetCore.Builder; using Microsoft.AspNetCore.Http; using Microsoft.AspNetCore.Routing; using Microsoft.eShopWeb.ApplicationCore.Services; using MinimalApi.Endpoint;  namespace Microsoft.eShopWeb.PublicApi.SubscriptionEndpoints;  public class ListSubscriptionPlansEndpoint : IEndpoint<IResult, ListSubscriptionPlansRequest> {     private readonly IMaxioClient _maxio;     private readonly MaxioSettings _settings;      public ListSubscriptionPlansEndpoint(IMaxioClient maxio, MaxioSettings settings)     {         _maxio = maxio;         _settings = settings;     }      public void AddRoute(IEndpointRouteBuilder app)     {         app.MapGet("api/subscription-plans",             async () => await HandleAsync(new ListSubscriptionPlansRequest()))             .Produces<ListSubscriptionPlansResponse>()             .WithTags("SubscriptionEndpoints")             .RequireAuthorization();     }      public async Task<IResult> HandleAsync(ListSubscriptionPlansRequest request)     {         var response = new ListSubscriptionPlansResponse(request.CorrelationId());         try         {             var products = await _maxio.ListProductsForFamilyAsync(_settings.ProductFamilyHandle);             foreach (var p in products)             {                 response.Plans.Add(new SubscriptionPlanDto                 {                     Id = p.Id,                     Handle = p.Handle,                     Name = p.Name,                     PriceMonthly = p.PriceInCents                 });             }         }                 catch (Exception ex)         {             return Results.BadRequest(new { error = "Failed to load plans: " + ex.Message });         }         return Results.Ok(response);     } }
